// Fixture bundle for pkg-size-guard tests.
export function handler0(event, options = {}) {
  const value = event.detail?.value ?? options.fallback ?? 0;
  if (typeof value !== 'number') throw new TypeError('handler0 expects a number');
  return { id: 'h0', value: value * 1, at: Date.now() };
}

